                    None => {
                        return Err(CompileError::LexerError(
                            "Unterminated string".to_string(),
                        ))
                    }
                }
            }
            Some('\n') => {
                self.line += 1;
                self.column = 1;
                s.push('\n');
                self.advance();
            }
            Some(c) => {
                s.push(c);
                self.advance();
            }
            None => {
                return Err(CompileError::LexerError(format!(
                    "Unterminated string starting at line {}",
                    start_line
                )))
            }
        }

        // ✅ Check string length limit
        if s.len() > MAX_STRING_LENGTH {
            return Err(CompileError::LexerError(
                format!("String too long (max {} bytes)", MAX_STRING_LENGTH)
            ));
        }
    }

    self.advance(); // Skip closing quote
    Ok(Token::String(s))
}
```

**Security Improvements**:
- ✅ Validates every escape sequence
- ✅ Rejects invalid escapes (e.g., `\z`, `\x`, `\u`)
- ✅ Supports null character (`\0`)
- ✅ Proper newline tracking in strings
- ✅ Length limit prevents unbounded allocation

