use fv_lang::lexer::{SecureLexer, Token};
use fv_lang::parser::Parser;
use fv_lang::ast::*;
use fv_lang::CompileError;

// ============================================================================
// 1단계: 기본 테스트 (10개)
// ============================================================================

#[test]
fn test_parse_simple_function() {
    let source = "fn add(x: i32, y: i32) -> i32 { return x + y; }";
    let lexer = SecureLexer::new(source).unwrap();
    let tokens = lexer.tokenize().unwrap();
    let parser = Parser::new(tokens).unwrap();
    let result = parser.parse();
    assert!(result.is_ok(), "단순 함수 파싱 실패");

    let program = result.unwrap();
    assert_eq!(program.definitions.len(), 1, "함수 정의 1개 필요");
}

#[test]
fn test_parse_function_with_body() {
    let source = "fn test() -> i32 { let x = 10; return x; }";
    let lexer = SecureLexer::new(source).unwrap();
    let tokens = lexer.tokenize().unwrap();
    let parser = Parser::new(tokens).unwrap();
    let result = parser.parse();
    assert!(result.is_ok(), "함수 본문 파싱 실패");
}

#[test]
fn test_parse_function_no_params() {
    let source = "fn get_answer() -> i32 { return 42; }";
    let lexer = SecureLexer::new(source).unwrap();
    let tokens = lexer.tokenize().unwrap();
    let parser = Parser::new(tokens).unwrap();
    let result = parser.parse();
    assert!(result.is_ok(), "매개변수 없는 함수 파싱 실패");
}

#[test]
fn test_parse_type_definition() {
    let source = "type UserId = i32;";
    let lexer = SecureLexer::new(source).unwrap();
    let tokens = lexer.tokenize().unwrap();

    let result = parser.parse();
    assert!(result.is_ok(), "단항 연산자 포함 if 표현식 파싱 실패");
}

