// src/symbols.rs (신규)
use std::collections::HashMap;

pub struct SymbolTable {
    scopes: Vec<HashMap<String, Symbol>>,
}

#[derive(Debug, Clone)]
pub struct Symbol {
    pub name: String,
    pub type_: Type,
    pub is_mutable: bool,
    pub scope_level: usize,
}

impl SymbolTable {
    pub fn new() -> Self {
        let mut table = SymbolTable {
            scopes: vec![],
        };
        table.enter_scope();  // 글로벌 스코프
        table
    }

    pub fn enter_scope(&mut self) {
        self.scopes.push(HashMap::new());
    }

    pub fn exit_scope(&mut self) {
        if self.scopes.len() > 1 {
            self.scopes.pop();
        }
    }

    pub fn define(&mut self, name: String, type_: Type, is_mutable: bool)
        -> Result<(), String>
    {
        let scope_level = self.scopes.len() - 1;

        if let Some(scope) = self.scopes.last_mut() {
            if scope.contains_key(&name) {
                return Err(format!("중복된 변수 정의: {}", name));
            }
            scope.insert(name.clone(), Symbol {
                name,
                type_,
                is_mutable,
                scope_level,
            });
            Ok(())
        } else {
            Err("스코프 없음".to_string())
        }
    }

    pub fn lookup(&self, name: &str) -> Option<Symbol> {
        for scope in self.scopes.iter().rev() {
            if let Some(symbol) = scope.get(name) {
                return Some(symbol.clone());
            }
        }
        None
    }
}
```

#### 1.3 타입 검사기

```rust
// src/type_checker.rs (신규)
pub struct TypeChecker {
    symbol_table: SymbolTable,
    errors: Vec<String>,
}

impl TypeChecker {
    pub fn new() -> Self {
        TypeChecker {
            symbol_table: SymbolTable::new(),
            errors: Vec::new(),
        }
    }

    pub fn check(&mut self, program: &Program) -> Result<(), Vec<String>> {
        for definition in &program.definitions {
            self.check_definition(definition)?;
        }

        if self.errors.is_empty() {
            Ok(())
        } else {
            Err(self.errors.clone())
        }
    }

    fn check_definition(&mut self, def: &Definition) -> Result<(), String> {
        match def {
            Definition::Function { name, params, body } => {
                self.symbol_table.enter_scope();

                // 매개변수 추가
                for param in params {
                    self.symbol_table.define(
                        param.clone(),
                        Type::Unknown,  // 타입 정보 추가 필요
                        false,
                    )?;
                }

                // 본문 검사
                for stmt in body {
                    self.check_statement(stmt)?;
                }

                self.symbol_table.exit_scope();
                Ok(())
            }
            Definition::TypeDef { name } => {
                // 타입 정의 검사
                Ok(())
            }
        }
    }

    fn check_statement(&mut self, stmt: &Statement) -> Result<Type, String> {
        match stmt {
            Statement::LetBinding { name, value } => {
                let value_type = self.check_expression(value)?;
                self.symbol_table.define(name.clone(), value_type.clone(), true)?;
                Ok(value_type)
            }
            Statement::Return(expr) => {
                self.check_expression(expr)
            }
            Statement::If { condition, then_branch, else_branch } => {
                let cond_type = self.check_expression(condition)?;

                if cond_type != Type::Boolean {
                    return Err("조건은 boolean이어야 함".to_string());
                }

                for stmt in then_branch {
                    self.check_statement(stmt)?;
                }

                if let Some(else_stmts) = else_branch {
                    for stmt in else_stmts {
                        self.check_statement(stmt)?;
                    }
                }

                Ok(Type::Unknown)
            }
            Statement::Expression(expr) => {
                self.check_expression(expr)
            }
        }
    }

    fn check_expression(&mut self, expr: &Expression) -> Result<Type, String> {
        match expr {
            Expression::Literal(lit) => {
                match lit {
                    Literal::Integer(_) => Ok(Type::Integer),
                    Literal::Float(_) => Ok(Type::Float),
                    Literal::String(_) => Ok(Type::String),
                    Literal::Boolean(_) => Ok(Type::Boolean),
                }
            }
            Expression::Variable(name) => {
                match self.symbol_table.lookup(name) {
                    Some(symbol) => Ok(symbol.type_),
                    None => Err(format!("정의되지 않은 변수: {}", name)),
                }
            }
            Expression::BinaryOp { op, left, right } => {
                let left_type = self.check_expression(left)?;
                let right_type = self.check_expression(right)?;

                // 연산자 타입 검사
                match op.as_str() {
                    "Plus" | "Minus" | "Star" | "Slash" | "Percent" => {
                        if left_type.is_numeric() && right_type.is_numeric() {
                            Ok(left_type)
                        } else {
                            Err(format!(
                                "산술 연산은 숫자 타입이어야 함: {:?} {} {:?}",
                                left_type, op, right_type
                            ))
                        }
                    }
                    "Eq" | "Ne" | "Lt" | "Le" | "Gt" | "Ge" => {
                        Ok(Type::Boolean)
                    }
                    "And" | "Or" => {
                        if left_type == Type::Boolean && right_type == Type::Boolean {
                            Ok(Type::Boolean)
                        } else {
                            Err("논리 연산은 boolean이어야 함".to_string())
                        }
                    }
                    _ => Err(format!("알 수 없는 연산자: {}", op)),
                }
            }
            Expression::FunctionCall { name, args } => {
                // 함수 호출 검사
                // TODO: 함수 시그니처 검사
                Ok(Type::Unknown)
            }
            _ => Ok(Type::Unknown),
        }
    }
}
